-- Source reset identity has no login/secret provisioned by this migration.
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'o_okul_reset_worker') THEN
    CREATE ROLE o_okul_reset_worker NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT NOREPLICATION NOBYPASSRLS;
  END IF;
END $$;
CREATE TABLE "TenantFreshResetOperation" (
  "id" text PRIMARY KEY, "tenantId" text NOT NULL REFERENCES "Tenant"("id") ON DELETE RESTRICT,
  "actorUserId" text NOT NULL, "idempotencyKey" text NOT NULL, "requestHash" text NOT NULL,
  "preset" text NOT NULL DEFAULT 'CLEAN_SETUP_V1' CHECK ("preset" = 'CLEAN_SETUP_V1'),
  "expectedLifecycleVersion" integer NOT NULL CHECK ("expectedLifecycleVersion" >= 0),
  "preflightDigest" text NOT NULL, "reason" text NOT NULL CHECK ("reason" IN ('SECURITY_REVIEW','INSTITUTION_REQUEST','OPERATIONS_REVIEW')),
  "status" text NOT NULL DEFAULT 'QUEUED' CHECK ("status" IN ('QUEUED','RUNNING','BLOCKED','FAILED','COMPLETED')),
  "phase" text NOT NULL DEFAULT 'PREFLIGHT' CHECK ("phase" IN ('PREFLIGHT','BACKUP','DATABASE','OBJECTS','VERIFY','DONE')),
  "errorCode" text, "backupReceipt" jsonb, "result" jsonb,
  "createdAt" timestamp(3) NOT NULL DEFAULT now(), "updatedAt" timestamp(3) NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX "TenantFreshResetOperation_tenantId_id_key" ON "TenantFreshResetOperation"("tenantId", "id");
CREATE UNIQUE INDEX "TenantFreshResetOperation_actorUserId_idempotencyKey_key" ON "TenantFreshResetOperation"("actorUserId", "idempotencyKey");
CREATE INDEX "TenantFreshResetOperation_tenantId_status_idx" ON "TenantFreshResetOperation"("tenantId", "status");
-- BLOCKED/FAILED retain ownership until this same operation is reconciled.
CREATE UNIQUE INDEX "TenantFreshResetOperation_one_unfinished" ON "TenantFreshResetOperation"("tenantId") WHERE "status" <> 'COMPLETED';
ALTER TABLE "TenantFreshResetOperation" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "TenantFreshResetOperation" FORCE ROW LEVEL SECURITY;
CREATE POLICY "TenantFreshResetOperation_tenant_isolation" ON "TenantFreshResetOperation"
  USING ("tenantId" = current_setting('app.current_tenant_id', true) OR current_setting('app.bypass_rls', true) = 'true')
  WITH CHECK ("tenantId" = current_setting('app.current_tenant_id', true) OR current_setting('app.bypass_rls', true) = 'true');
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app') THEN
    GRANT SELECT, INSERT, UPDATE ON "TenantFreshResetOperation" TO app;
    REVOKE DELETE ON "TenantFreshResetOperation" FROM app;
  END IF;
END $$;
