CREATE FUNCTION o_okul_block_active_during_reset() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW."status" = 'ACTIVE' AND OLD."status" <> 'ACTIVE' AND EXISTS (
    SELECT 1 FROM "TenantFreshResetOperation" WHERE "tenantId" = NEW."id" AND "status" <> 'COMPLETED'
  ) THEN RAISE EXCEPTION USING MESSAGE = 'RESET_OPERATION_IN_PROGRESS'; END IF;
  RETURN NEW;
END $$;
CREATE TRIGGER "Tenant_block_active_during_reset" BEFORE UPDATE OF "status" ON "Tenant"
FOR EACH ROW EXECUTE FUNCTION o_okul_block_active_during_reset();
